/* ============================================================
   YARDIMCI FONKSİYONLAR
   ============================================================ */

function normalizeTr(str) {
  return str
    .toLocaleLowerCase("tr-TR")
    .replace(/ı/g, "i")
    .replace(/İ/g, "i")
    .replace(/ç/g, "c")
    .replace(/ş/g, "s")
    .replace(/ğ/g, "g")
    .replace(/ü/g, "u")
    .replace(/ö/g, "o");
}

function playerSearchTokens(p) {
  const names = [p.name, ...(p.aliases || [])];
  return names.map((n) => normalizeTr(n));
}

function findPlayersByQuery(nv, limit = 8) {
  if (!nv) return [];
  const scored = [];
  PLAYERS.forEach((p) => {
    const tokens = playerSearchTokens(p);
    const last = normalizeTr(p.name.split(" ").pop() || "");
    let score = 0;
    if (tokens.some((t) => t === nv) || last === nv) score = 3;
    else if (tokens.some((t) => t.startsWith(nv) || last.startsWith(nv))) score = 2;
    else if (tokens.some((t) => t.includes(nv))) score = 1;
    if (score > 0) scored.push({ p, score });
  });
  scored.sort((a, b) => b.score - a.score || a.p.name.localeCompare(b.p.name));
  return scored.slice(0, limit).map((x) => x.p);
}

function findPlayerByGuess(raw) {
  const nv = normalizeTr((raw || "").trim());
  if (!nv || nv.length < 2) return { player: null, ambiguous: false };
  const exact = PLAYERS.filter((p) => {
    const tokens = playerSearchTokens(p);
    const last = normalizeTr(p.name.split(" ").pop() || "");
    return tokens.some((t) => t === nv) || last === nv;
  });
  if (exact.length === 1) return { player: exact[0], ambiguous: false };
  if (exact.length > 1) {
    const uniqueLast = exact.filter((p) => normalizeTr(p.name.split(" ").pop() || "") === nv);
    if (uniqueLast.length === 1) return { player: uniqueLast[0], ambiguous: false };
    return { player: null, ambiguous: true };
  }
  const partial = findPlayersByQuery(nv, 6);
  if (partial.length === 1) return { player: partial[0], ambiguous: false };
  if (partial.length > 1) return { player: null, ambiguous: true };
  return { player: null, ambiguous: false };
}

function buildClubPairIndex() {
  const byClub = {};
  PLAYERS.forEach((p) => {
    const unique = [...new Set((p.clubs || []).filter((c) => CLUBS[c]))];
    unique.forEach((c) => {
      if (!byClub[c]) byClub[c] = [];
      byClub[c].push(p.id);
    });
  });
  const clubIds = Object.keys(CLUBS).filter((c) => byClub[c] && byClub[c].length);
  const pairs = [];
  for (let i = 0; i < clubIds.length; i++) {
    for (let j = i + 1; j < clubIds.length; j++) {
      const a = clubIds[i], b = clubIds[j];
      const common = (byClub[a] || []).filter((pid) => (byClub[b] || []).includes(pid));
      if (common.length > 0) pairs.push({ a, b, common });
    }
  }
  return pairs;
}

const CLUB_PAIRS = buildClubPairIndex();

// Fisher-Yates
function shuffleArray(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// tüm eşleşmeleri karışık sırada ve sol/sağ takım rastgele döndürülmüş halde döndürür
// böylece art arda oynanan turlarda hem eşleşme hem de görünüm örüntüsü tekrar etmez
function pickWeightedPairs() {
  const easy = CLUB_PAIRS.filter((p) => p.common.length === 1);
  const mid = CLUB_PAIRS.filter((p) => p.common.length >= 2 && p.common.length <= 3);
  const hard = CLUB_PAIRS.filter((p) => p.common.length >= 4);
  const mix = [
    ...shuffleArray(easy).slice(0, Math.max(24, Math.floor(easy.length * 0.55))),
    ...shuffleArray(mid).slice(0, Math.max(16, Math.floor(mid.length * 0.7))),
    ...shuffleArray(hard).slice(0, Math.max(8, Math.floor(hard.length * 0.4))),
  ];
  return shuffleArray(mix.length ? mix : CLUB_PAIRS);
}

function shuffledPairPool() {
  return pickWeightedPairs().map((p) =>
    Math.random() < 0.5 ? p : { a: p.b, b: p.a, common: p.common }
  );
}

// Zorluk ayarına göre kaç şıkkın "ilgili" (ekrandaki kulüplerden en az birinde
// oynamış) kaç şıkkın "aynı lig" (o kulüplerde oynamamış ama aynı ülkede/ligde
// oynamış) havuzundan geleceğini belirler. Doğru cevap her zaman iki kulüpte de
// oynamış tek futbolcudur.
const DIFFICULTY_MIX = {
  easy: { related: 1, sameLeague: 2 }, // Kolay: sadece 2 futbolcu (doğru cevap + 1) o takımlarda oynamış
  mid: { related: 2, sameLeague: 1 }, // Orta: 3 futbolcu (doğru cevap + 2) o takımlarda oynamış
  hard: { related: 3, sameLeague: 0 }, // Zor: 4 futbolcunun 4'ü de o takımlarda oynamış
};

// bir soru için 4 seçenekli mod seçeneklerini üretir: doğru cevap + zorluk
// ayarına göre "ilgili" (kulüplerden en az birinde forma giymiş) ve "aynı lig"
// (o kulüplerde oynamamış ama aynı ülkede oynamış) havuzlarından seçilen
// çeldiriciler. Yeterli aday yoksa kademeli olarak daha geniş havuzlarla tamamlanır.
function buildMcOptionIds(correctIds, clubA, clubB, difficulty = "hard") {
  const correctId = correctIds[Math.floor(Math.random() * correctIds.length)];
  const mix = DIFFICULTY_MIX[difficulty] || DIFFICULTY_MIX.hard;

  const relatedPool = shuffleArray(
    PLAYERS.filter(
      (p) => !correctIds.includes(p.id) && ((p.clubs || []).includes(clubA) || (p.clubs || []).includes(clubB))
    )
  );

  const leagues = new Set(
    [CLUBS[clubA]?.country, CLUBS[clubB]?.country].filter(Boolean)
  );
  const sameLeaguePool = shuffleArray(
    PLAYERS.filter(
      (p) =>
        !correctIds.includes(p.id) &&
        !(p.clubs || []).includes(clubA) &&
        !(p.clubs || []).includes(clubB) &&
        (p.clubs || []).some((c) => CLUBS[c] && leagues.has(CLUBS[c].country))
    )
  );

  const usedIds = new Set([correctId]);
  const distractors = [];

  const takeFrom = (pool, count) => {
    let taken = 0;
    for (const p of pool) {
      if (taken >= count) break;
      if (usedIds.has(p.id)) continue;
      distractors.push(p.id);
      usedIds.add(p.id);
      taken++;
    }
  };

  takeFrom(relatedPool, mix.related);
  takeFrom(sameLeaguePool, mix.sameLeague);

  // Yeterli aday bulunamazsa kademeli olarak daha geniş havuzlarla tamamla
  if (distractors.length < 3) takeFrom(relatedPool, 3 - distractors.length);
  if (distractors.length < 3) takeFrom(sameLeaguePool, 3 - distractors.length);
  if (distractors.length < 3) {
    const fallbackPool = shuffleArray(
      PLAYERS.filter((p) => !correctIds.includes(p.id) && !usedIds.has(p.id))
    );
    takeFrom(fallbackPool, 3 - distractors.length);
  }

  return shuffleArray([correctId, ...distractors.slice(0, 3)]);
}

function pairToQuestion(pick, difficulty = "hard") {
  return {
    key: `${[pick.a, pick.b].sort().join("|")}`,
    clubA: pick.a,
    clubB: pick.b,
    answers: pick.common,
    mcOptionIds: buildMcOptionIds(pick.common, pick.a, pick.b, difficulty),
  };
}

function mcOptionsFromQuestion(question) {
  return (question?.mcOptionIds || []).map((id) => PLAYERS.find((p) => p.id === id)).filter(Boolean);
}

function roomCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let out = "";
  for (let i = 0; i < 6; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}

// hızlı cevaba daha yüksek puan: süre bittiğine ne kadar yakınsa o kadar az puan
function calcPoints(elapsedMs, totalSeconds, streak = 0) {
  const totalMs = totalSeconds * 1000;
  const frac = Math.max(0, Math.min(1, 1 - elapsedMs / totalMs));
  const base = Math.max(10, Math.round(10 + frac * 90));
  const bonus = Math.min(40, Math.max(0, streak) * 5);
  return base + bonus;
}

// tur zorluğu: iki kulüpte birden oynamış kaç futbolcu varsa o kadar kolay
function difficultyInfo(commonCount) {
  if (commonCount >= 4) return { label: "Kolay", cls: "diff-easy" };
  if (commonCount >= 2) return { label: "Orta", cls: "diff-mid" };
  return { label: "Zor", cls: "diff-hard" };
}

function readHighScore() {
  try {
    const v = parseInt(localStorage.getItem(HIGH_SCORE_KEY) || "0", 10);
    return Number.isFinite(v) ? v : 0;
  } catch (e) {
    return 0;
  }
}

function writeHighScore(v) {
  try { localStorage.setItem(HIGH_SCORE_KEY, String(v)); } catch (e) { /* yut */ }
}

// window.storage (Claude artifact ortamı) yoksa localStorage'a düşen basit uyumluluk katmanı.
// Not: localStorage yalnızca AYNI TARAYICIDA sekmeler arasında paylaşılır — farklı bilgisayarlar
// arasında gerçek zamanlı eşleşme için gerçek bir backend (ör. Socket.IO) gerekir.
const storage = {
  async get(key, shared) {
    if (typeof window !== "undefined" && window.storage && typeof window.storage.get === "function") {
      return window.storage.get(key, shared);
    }
    try {
      const v = localStorage.getItem(key);
      if (v === null) return null;
      return { key, value: v, shared: !!shared };
    } catch (e) { return null; }
  },
  async set(key, value, shared) {
    if (typeof window !== "undefined" && window.storage && typeof window.storage.set === "function") {
      return window.storage.set(key, value, shared);
    }
    try {
      localStorage.setItem(key, value);
      return { key, value, shared: !!shared };
    } catch (e) { return null; }
  },
};

/* ============================================================
   KULÜP ROZETİ (AMBLEM)
   Gerçek amblemler TheSportsDB'nin ücretsiz, imza gerektirmeyen
   herkese açık API'sinden çekilir (thesportsdb.com/api/v1/json/3/
   searchteams.php). Bu, Wikidata'nın aksine özellikle spor takımı
   rozetleri için küratörlüğü yapılmış bir veritabanıdır; bu yüzden
   "stadyum fotoğrafı" gibi alakasız sonuç verme riski çok düşüktür.
   Yine de bir kulüp bu veritabanında bulunamazsa veya görsel
   yüklenemezse (ör. ağ sorunu), kulübün rengine göre üretilen şık
   bir SVG rozete otomatik olarak düşülür — asla bozuk/yanlış bir
   görsel gösterilmez.
   Not: Bu istekler tarayıcıda (kullanıcının kendi sitesinde) çalışır;
   Claude'un önizleme/yayın ortamı dış görselleri engelliyorsa (CSP)
   otomatik olarak SVG rozete düşer, dosya yine de bozulmaz.
   ============================================================ */

const BADGE_CACHE = {};
const BADGE_FETCH_TIMEOUT_MS = 6000;
const SPORTSDB_KEY = "123"; // TheSportsDB herkese açık ücretsiz anahtar (eski "3" test anahtarı artık devre dışı)

/* Türkçe/İskandinav/Slav gibi dillerdeki aksanlı harfleri TheSportsDB'nin
   arama motoru genelde tanımadığı için ("Beşiktaş" -> 0 sonuç ama
   "Besiktas" -> eşleşme bulur) ASCII'ye katlanmış bir varyant da üretiyoruz. */
function asciiFold(s) {
  return String(s || "")
    .replace(/ı/g, "i")
    .replace(/İ/g, "I")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/Ø/g, "O")
    .replace(/ø/g, "o")
    .replace(/Đ/g, "D")
    .replace(/đ/g, "d")
    .trim();
}

/* Kulübün resmi/uzun adının başındaki veya sonundaki jenerik kısaltmaları
   (FC, AC, 1. FC, K.R.C., S.C. vb.) çıkarır; böylece TheSportsDB'de kısa
   adla kayıtlı takımlar da (örn. "1. FC Köln" -> "Köln") bulunabilir. */
function stripClubWords(s) {
  return String(s || "")
    .replace(/^(1\.?\s*)?(FC|AFC|AC|AS|CA|CD|CF|SK|SC|SS|SSC|UC|US|RC|RCD|VfL|VfB|TSG|FK|GNK|K\.?R\.?C\.?|R\.?S\.?C\.?|S\.?L\.?|S\.?C\.?P\.?)\.?\s+/i, "")
    .replace(/\s+(F\.?C\.?|A\.?F\.?C\.?|S\.?K\.?|S\.?C\.?|CFC|J\.?K\.?|Calcio.*|Club de.*|1913|1909|05)$/i, "")
    .trim();
}

function badgeNameCandidates(club) {
  const raw = [club.wiki, club.name].filter(Boolean);
  const variants = new Set();
  for (const n of raw) {
    const stripped = stripClubWords(n);
    for (const v of [n, stripped]) {
      if (!v) continue;
      variants.add(v);
      const folded = asciiFold(v);
      if (folded && folded !== v) variants.add(folded);
      const bare = v.replace(/[.'’]/g, "").replace(/\s{2,}/g, " ").trim();
      if (bare && bare !== v) variants.add(bare);
    }
  }
  return [...variants];
}

async function fetchJsonWithTimeout(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), BADGE_FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) return null;
    return await res.json();
  } catch (e) {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function normalizeForMatch(s) {
  return String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

/* KAYNAK 1: Wikipedia REST API (anahtar gerektirmez, CORS'a tam uyumlu).
   Kulüp verisindeki "wiki" alanı zaten İngilizce Wikipedia makale başlığı
   olduğundan, o makalenin bilgi kutusundaki görsel (originalimage/thumbnail)
   neredeyse her zaman kulüp amblemidir. TheSportsDB'nin bot/CORS koruması
   yüzünden tarayıcıdan engellenebildiği durumlarda bu kaynak çalışmaya
   devam eder. */
async function fetchBadgeFromWikipedia(title) {
  if (!title) return null;
  try {
    const clean = String(title).trim().replace(/\s+/g, "_");
    const url = `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(clean)}`;
    const data = await fetchJsonWithTimeout(url);
    if (!data || data.type === "disambiguation" || data.type === "no-extract") return null;
    return data?.originalimage?.source || data?.thumbnail?.source || null;
  } catch (e) {
    return null;
  }
}

/* KAYNAK 2: TheSportsDB (yedek). */
async function fetchBadgeFromSportsDb(name) {
  if (!name) return null;
  const url = `https://www.thesportsdb.com/api/v1/json/${SPORTSDB_KEY}/searchteams.php?t=${encodeURIComponent(name)}`;
  const data = await fetchJsonWithTimeout(url);
  const teams = data?.teams;
  if (!Array.isArray(teams) || teams.length === 0) return null;
  const soccerTeams = teams.filter((t) => (t.strSport || "").toLowerCase() === "soccer");
  const pool = soccerTeams.length ? soccerTeams : teams;
  const target = normalizeForMatch(name);
  const exact = pool.find((t) => normalizeForMatch(t.strTeam) === target);
  const best = exact || pool[0];
  return best?.strTeamBadge || best?.strTeamLogo || null;
}

async function resolveClubBadgeUrl(club) {
  // Önce Wikipedia'yı dene (club.wiki, sonra club.name).
  for (const name of [club.wiki, club.name].filter(Boolean)) {
    const badge = await fetchBadgeFromWikipedia(name);
    if (badge) return badge;
  }
  // Wikipedia'da bulunamazsa TheSportsDB'deki tüm varyantları dene.
  const candidates = badgeNameCandidates(club);
  for (const name of candidates) {
    const badge = await fetchBadgeFromSportsDb(name);
    if (badge) return badge;
  }
  return null;
}

function useClubBadge(clubId) {
  const [url, setUrl] = useState(() => BADGE_CACHE[clubId] || null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setFailed(false);
    if (BADGE_CACHE[clubId]) { setUrl(BADGE_CACHE[clubId]); return; }
    setUrl(null);
    const club = CLUBS[clubId];
    if (!club) { setFailed(true); return; }

    (async () => {
      try {
        const found = await resolveClubBadgeUrl(club);
        if (cancelled) return;
        if (found) { BADGE_CACHE[clubId] = found; setUrl(found); return; }
        if (typeof console !== "undefined") {
          console.warn(`[ClubCrest] "${club.name}" için amblem bulunamadı (Wikipedia + TheSportsDB). Tarayıcı konsolunda ayrıca kırmızı bir ağ hatası (CORS/CSP/İstek engellendi) görüyorsan, hosting ortamının bu iki dış siteye (en.wikipedia.org, www.thesportsdb.com) çıkışı engellediği anlamına gelir.`);
        }
      } catch (e) {
        if (typeof console !== "undefined") console.warn(`[ClubCrest] "${club?.name}" için hata:`, e);
      }
      if (!cancelled) setFailed(true);
    })();

    return () => { cancelled = true; };
  }, [clubId]);

  return { url, failed };
}

function hashStr(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function shadeHexColor(hex, percent) {
  let h = (hex || "#888888").replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  if (h.length !== 6) h = "888888";
  const num = parseInt(h, 16);
  const amt = Math.round(255 * percent);
  let r = (num >> 16) + amt;
  let g = ((num >> 8) & 0x00ff) + amt;
  let b = (num & 0x0000ff) + amt;
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));
  return `#${(1 << 24 | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;
}

function isLightHex(hex) {
  let h = (hex || "#888888").replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  if (h.length !== 6) return false;
  const num = parseInt(h, 16);
  const r = num >> 16, g = (num >> 8) & 255, b = num & 255;
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.62;
}

const CREST_SHAPES = [
  // klasik sivri kalkan
  "M50 2 L94 16 V56 C94 84 76 100 50 110 C24 100 6 84 6 56 V16 Z",
  // yuvarlak hatlı kalkan
  "M50 3 C74 3 92 12 92 12 V54 C92 82 74 98 50 109 C26 98 8 82 8 54 V12 C8 12 26 3 50 3 Z",
  // madalyon / yuvarlak rozet
  "M50 4 A46 46 0 1 1 49.9 4 Z",
  // altıgen rozet
  "M50 2 L91 26 V80 L50 110 L9 80 V26 Z",
];

function ClubCrest({ clubId, size = 92 }) {
  const club = CLUBS[clubId];
  const { url, failed } = useClubBadge(clubId);
  const [imgError, setImgError] = useState(false);
  useEffect(() => { setImgError(false); }, [clubId]);
  if (!club) return null;
  const showImage = url && !failed && !imgError;
  const isLoading = !url && !failed && !imgError;
  const initials = club.short.slice(0, 3);

  const h = hashStr(clubId);
  const shapePath = CREST_SHAPES[h % CREST_SHAPES.length];
  const baseColor = club.color || "#8a8a8a";
  const lightTone = isLightHex(baseColor);
  const colorA = shadeHexColor(baseColor, lightTone ? -0.06 : 0.16);
  const colorB = shadeHexColor(baseColor, lightTone ? -0.22 : -0.28);
  const ringColor = shadeHexColor(baseColor, lightTone ? -0.35 : 0.3);
  const textColor = lightTone ? "rgba(15,20,15,0.78)" : "rgba(255,255,255,0.96)";
  const gradId = `crestGrad-${clubId}`;
  const sheenId = `crestSheen-${clubId}`;

  return (
    <div className="crest-wrap">
      <div className="crest-badge" style={{ "--crest-color": club.color, width: size, height: size }}>
        {isLoading ? (
          <div className="crest-loading" aria-hidden="true" />
        ) : showImage ? (
          <img
            src={url}
            alt={club.name}
            className="crest-img"
            referrerPolicy="no-referrer"
            onError={() => setImgError(true)}
          />
        ) : (
          <svg width={size} height={size} viewBox="0 0 100 112" className="crest-svg">
            <defs>
              <linearGradient id={gradId} x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stopColor={colorA} />
                <stop offset="1" stopColor={colorB} />
              </linearGradient>
              <linearGradient id={sheenId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#fff" stopOpacity="0.4" />
                <stop offset="0.45" stopColor="#fff" stopOpacity="0" />
              </linearGradient>
            </defs>
            <path d={shapePath} fill={ringColor} opacity="0.9" />
            <path
              d={shapePath}
              fill={`url(#${gradId})`}
              stroke="rgba(255,255,255,0.28)"
              strokeWidth="1.5"
              transform="scale(0.93)"
              transformOrigin="50px 56px"
            />
            <path d={shapePath} fill={`url(#${sheenId})`} opacity="0.55" transform="scale(0.93)" transformOrigin="50px 56px" />
            <line x1="18" y1="58" x2="82" y2="58" stroke="rgba(255,255,255,0.22)" strokeWidth="1.5" />
            <text
              x="50"
              y="52"
              textAnchor="middle"
              fontSize="24"
              fontWeight="800"
              letterSpacing="0.5"
              fill={textColor}
              style={{ filter: "drop-shadow(0 1px 1px rgba(0,0,0,0.35))" }}
            >
              {initials}
            </text>
            <text
              x="50"
              y="72"
              textAnchor="middle"
              fontSize="8.5"
              fontWeight="700"
              letterSpacing="1.5"
              fill={textColor}
              opacity="0.75"
            >
              {(club.country || "").slice(0, 3).toUpperCase()}
            </text>
          </svg>
        )}
      </div>
      <div className="crest-label">
        <div className="crest-name">{club.name}</div>
        <div className="crest-country">{club.country}</div>
      </div>
    </div>
  );
}

function ScoreDigits({ value, digits = 2 }) {
  const str = String(value).padStart(digits, "0");
  return (
    <div className="digit-row">
      {str.split("").map((d, i) => (
        <span key={i} className="digit">{d}</span>
      ))}
    </div>
  );
}

