/* ---------- Autocomplete girişi ---------- */

function AnswerInput({ disabled, onSubmit, revealCorrectId }) {
  const [value, setValue] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [activeIdx, setActiveIdx] = useState(-1);
  const inputRef = useRef(null);

  useEffect(() => {
    setValue("");
    setSuggestions([]);
    setActiveIdx(-1);
    if (!disabled && inputRef.current) inputRef.current.focus();
  }, [disabled, revealCorrectId]);

  function handleChange(e) {
    const v = e.target.value;
    setValue(v);
    if (v.trim().length === 0) {
      setSuggestions([]);
      return;
    }
    const nv = normalizeTr(v.trim());
    const matches = PLAYERS.filter((p) => normalizeTr(p.name).includes(nv)).slice(0, 6);
    setSuggestions(matches);
    setActiveIdx(-1);
  }

  function commit(player) {
    if (!player || disabled) return;
    onSubmit(player);
    setValue(player.name);
    setSuggestions([]);
  }

  function handleKeyDown(e) {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIdx((i) => Math.min(i + 1, suggestions.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIdx((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      if (activeIdx >= 0 && suggestions[activeIdx]) commit(suggestions[activeIdx]);
      else if (suggestions[0]) commit(suggestions[0]);
    }
  }

  return (
    <div className="answer-wrap">
      <div className="answer-inputbar">
        <input
          ref={inputRef}
          className="answer-input"
          placeholder={disabled ? "Tur bekleniyor…" : "Futbolcu adı yaz…"}
          value={value}
          disabled={disabled}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          autoComplete="off"
          spellCheck={false}
        />
        <button
          className="answer-send"
          disabled={disabled || suggestions.length === 0}
          onClick={() => commit(activeIdx >= 0 ? suggestions[activeIdx] : suggestions[0])}
        >
          Gönder
        </button>
      </div>
      {suggestions.length > 0 && (
        <div className="suggestion-list">
          {suggestions.map((p, i) => (
            <button
              key={p.id}
              className={"suggestion-item" + (i === activeIdx ? " active" : "")}
              onMouseDown={(e) => { e.preventDefault(); commit(p); }}
            >
              <span className="sugg-name">{p.name}</span>
              <span className="sugg-meta">{p.pos} · {p.age}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------- 4 seçenekli cevap ---------- */

function MultipleChoiceAnswer({ options, correctIds, disabled, onSubmit, revealCorrectId }) {
  const [selectedId, setSelectedId] = useState(null);

  useEffect(() => {
    setSelectedId(null);
  }, [disabled, revealCorrectId]);

  function handlePick(player) {
    if (disabled || selectedId) return;
    setSelectedId(player.id);
    onSubmit(player);
  }

  useEffect(() => {
    function handleKey(e) {
      const n = parseInt(e.key, 10);
      if (n >= 1 && n <= options.length) handlePick(options[n - 1]);
    }
    window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [options, disabled, selectedId]);

  return (
    <div className="mc-grid">
      {options.map((p, i) => {
        const isSelected = selectedId === p.id;
        const isCorrect = (correctIds || []).includes(p.id);
        let cls = "mc-option";
        if (disabled && isCorrect) cls += " mc-correct";
        else if (disabled && isSelected && !isCorrect) cls += " mc-wrong";
        else if (isSelected) cls += " mc-selected";
        return (
          <button key={p.id} type="button" className={cls} disabled={disabled} onClick={() => handlePick(p)}>
            <span className="mc-key">{i + 1}</span>
            <span className="mc-name">{p.name}</span>
            {p.pos && <span className="mc-pos">{p.pos}</span>}
          </button>
        );
      })}
    </div>
  );
}

/* ---------- Tek kişilik oyun ---------- */

function SoloGame({ onExit, totalSeconds, gameMode, difficulty, playerName }) {
  const queueRef = useRef(shuffledPairPool());
  const drawNext = useCallback(() => {
    if (queueRef.current.length === 0) queueRef.current = shuffledPairPool();
    return pairToQuestion(queueRef.current.shift(), difficulty);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [difficulty]);

  const [question, setQuestion] = useState(() => drawNext());
  const [timeLeft, setTimeLeft] = useState(totalSeconds); // OYUNUN TOPLAM kalan süresi
  const [phase, setPhase] = useState("playing"); // playing | reveal | ended
  const [feedback, setFeedback] = useState(null); // 'correct' | 'wrong' | 'skip' | null
  const [lastPoints, setLastPoints] = useState(0);
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(() => readHighScore());
  const [stats, setStats] = useState({ correct: 0, wrong: 0, skipped: 0, roundsPlayed: 0 });
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [confirmExit, setConfirmExit] = useState(false);
  const roundStartRef = useRef(Date.now());
  const revealTimeoutRef = useRef(null);
  const phaseRef = useRef(phase);
  phaseRef.current = phase;

  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      writeHighScore(score);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [score]);

  // Tek bir toplam-süre sayacı: turlar değişse de bu sayaç kesintisiz akar,
  // 0'a ulaştığında oyun biter (artık her turun kendi süresi yok).
  useEffect(() => {
    const tick = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          clearInterval(tick);
          clearTimeout(revealTimeoutRef.current);
          setPhase("ended");
          return 0;
        }
        return t - 1;
      });
    }, 1000);
    return () => clearInterval(tick);
  }, []);

  useEffect(() => () => clearTimeout(revealTimeoutRef.current), []);

  function goNext() {
    if (phaseRef.current === "ended") return;
    setQuestion(drawNext());
    setPhase("playing");
    setFeedback(null);
    roundStartRef.current = Date.now();
  }

  function handleSkip() {
    if (phase !== "playing") return;
    setPhase("reveal");
    setFeedback("skip");
    setLastPoints(0);
    setStats((s) => ({ ...s, roundsPlayed: s.roundsPlayed + 1, skipped: s.skipped + 1 }));
    revealTimeoutRef.current = setTimeout(goNext, 1000);
  }

  function handleSubmit(player) {
    if (phase !== "playing") return;
    const elapsed = Date.now() - roundStartRef.current;
    const isCorrect = question.answers.includes(player.id);
    const points = isCorrect ? calcPoints(elapsed, SCORE_SPEED_WINDOW_S, streak) : 0;
    setPhase("reveal");
    setFeedback(isCorrect ? "correct" : "wrong");
    setLastPoints(points);
    if (points > 0) setScore((s) => s + points);
    setStats((s) => ({
      ...s,
      correct: s.correct + (isCorrect ? 1 : 0),
      wrong: s.wrong + (isCorrect ? 0 : 1),
      roundsPlayed: s.roundsPlayed + 1,
    }));
    setStreak((prev) => {
      const next = isCorrect ? prev + 1 : 0;
      setBestStreak((b) => Math.max(b, next));
      return next;
    });
    revealTimeoutRef.current = setTimeout(goNext, isCorrect ? 1100 : 1800);
  }

  const answerNames = question.answers.map((id) => PLAYERS.find((p) => p.id === id)?.name).filter(Boolean);
  const mcOptions = mcOptionsFromQuestion(question);

  if (phase === "ended") {
    const isNewHigh = score >= highScore && score > 0;
    return (
      <div className="screen">
        <TopBar onBack={onExit} title="Sonuç" />
        <div className="result-panel">
          <Trophy size={40} color="#E8B33D" />
          <div className="result-title">Süre Doldu!</div>
          <p className="duration-intro" style={{ margin: 0 }}>
            {playerName ? <strong>{playerName}</strong> : "Oyuncu"}, işte performansın:
          </p>
          <ScoreDigits value={score} digits={String(score).length > 2 ? String(score).length : 2} />
          {isNewHigh && <div className="highscore-pill"><Trophy size={14} /> Yeni rekor!</div>}
          <div className="stats-strip">
            <span>Doğru: {stats.correct}</span>
            <span>Yanlış: {stats.wrong}</span>
            <span>Geçilen: {stats.skipped}</span>
            <span>En iyi seri: {bestStreak}</span>
          </div>
          <button className="menu-card primary" onClick={onExit}><RotateCcw size={18} /><span>Ana Menüye Dön</span></button>
        </div>
      </div>
    );
  }

  return (
    <div className="screen">
      <TopBar
        onBack={() => setConfirmExit(true)}
        title={gameMode === "mc" ? "Tek Kişilik · 4 Seçenek" : "Tek Kişilik · Yazarak"}
        right={<div className="streak-pill"><Flame size={14} /> {streak}</div>}
      />

      <div className="hud-row">
        <div className="hud-chip">
          <div className="hud-label">Tur</div>
          <div className="hud-value">{stats.roundsPlayed + 1}</div>
        </div>
        <div className={"hud-chip timer" + (timeLeft <= 10 ? " urgent" : "")}>
          <div className="hud-label">Toplam Süre</div>
          <ScoreDigits value={timeLeft} />
        </div>
        <div className="hud-chip">
          <div className="hud-label">Skor</div>
          <div className="hud-value">{score}</div>
        </div>
      </div>

      <div className="timer-track">
        <div
          className={"timer-fill" + (timeLeft <= 10 ? " urgent" : "")}
          style={{ width: `${Math.max(0, (timeLeft / totalSeconds) * 100)}%` }}
        />
      </div>

      <div className="highscore-row">
        <Trophy size={13} /> En Yüksek: <strong>{Math.max(highScore, score)}</strong>
      </div>

      <div className={"matchup " + (feedback === "correct" ? "flash-green" : feedback === "wrong" ? "flash-red" : "")}>
        <ClubCrest clubId={question.clubA} />
        <div className="vs">
          VS
          <span className={"diff-badge " + difficultyInfo(question.answers.length).cls}>
            {difficultyInfo(question.answers.length).label}
          </span>
        </div>
        <ClubCrest clubId={question.clubB} />
      </div>

      {phase === "reveal" && (
        <div className={"reveal-banner " + (feedback === "correct" ? "reveal-ok" : feedback === "skip" ? "reveal-skip" : "reveal-fail")}>
          {feedback === "correct" ? `Doğru! +${lastPoints} puan — ` : feedback === "skip" ? "Geçildi — doğru cevap: " : "Yanlış — doğru cevap: "}
          <strong>{answerNames.join(" / ")}</strong>
        </div>
      )}

      {gameMode === "mc" ? (
        <MultipleChoiceAnswer
          options={mcOptions}
          correctIds={question.answers}
          disabled={phase !== "playing"}
          onSubmit={handleSubmit}
          revealCorrectId={question.key}
        />
      ) : (
        <AnswerInput disabled={phase !== "playing"} onSubmit={handleSubmit} revealCorrectId={question.key} />
      )}

      <button className="skip-btn" disabled={phase !== "playing"} onClick={handleSkip}>
        Soruyu Geç →
      </button>

      <div className="stats-strip">
        <span>Doğru: {stats.correct}</span>
        <span>Yanlış: {stats.wrong}</span>
        <span>Geçilen: {stats.skipped}</span>
        <span>En iyi seri: {bestStreak}</span>
      </div>

      {confirmExit && (
        <ConfirmExitModal onConfirm={onExit} onCancel={() => setConfirmExit(false)} />
      )}
    </div>
  );
}

/* ---------- Çok kişilik: Lobi (oda kur / katıl) ---------- */

function MultiLobby({ onExit, onEnterRoom, roomStateRef, roundSeconds, gameMode, difficulty, initialName }) {
  const [mode, setMode] = useState("choose"); // choose | waiting
  const [name, setName] = useState(initialName || "");
  const [joinCode, setJoinCode] = useState("");
  const [code, setCode] = useState("");
  const [error, setError] = useState("");
  const [copied, setCopied] = useState(false);
  const pollRef = useRef(null);

  function makeQuestionSet(n) {
    return shuffledPairPool().slice(0, n).map((pick) => pairToQuestion(pick, difficulty));
  }

  async function createRoom() {
    if (!name.trim()) { setError("Önce adını yaz."); return; }
    setError("");
    const c = roomCode();
    const doc = {
      code: c,
      status: "waiting",
      roundSeconds,
      gameMode,
      players: { host: { name: name.trim() }, guest: null },
      scores: { host: 0, guest: 0 },
      round: 0,
      questions: null,
      roundStartedAt: null,
      answers: {},
      createdAt: Date.now(),
    };
    try {
      await storage.set(`ff-room:${c}`, JSON.stringify(doc), true);
      setCode(c);
      setMode("waiting");
      startWaitPoll(c, "host");
    } catch (e) {
      setError("Oda oluşturulamadı, tekrar dene.");
    }
  }

  async function joinRoom() {
    if (!name.trim()) { setError("Önce adını yaz."); return; }
    if (joinCode.trim().length < 6) { setError("6 haneli kodu gir."); return; }
    setError("");
    const c = joinCode.trim().toUpperCase();
    try {
      const res = await storage.get(`ff-room:${c}`, true);
      if (!res) { setError("Böyle bir oda bulunamadı."); return; }
      const doc = JSON.parse(res.value);
      if (doc.status !== "waiting") { setError("Bu oda dolu veya oyun başlamış."); return; }
      doc.players.guest = { name: name.trim() };
      doc.status = "playing";
      doc.round = 1;
      doc.questions = makeQuestionSet(TOTAL_ROUNDS);
      doc.roundStartedAt = Date.now();
      doc.answers = {};
      await storage.set(`ff-room:${c}`, JSON.stringify(doc), true);
      setCode(c);
      roomStateRef.current = { code: c, role: "guest", myName: name.trim() };
      onEnterRoom();
    } catch (e) {
      setError("Odaya katılırken bir sorun oluştu.");
    }
  }

  function startWaitPoll(c, myRole) {
    clearInterval(pollRef.current);
    pollRef.current = setInterval(async () => {
      try {
        const res = await storage.get(`ff-room:${c}`, true);
        if (!res) return;
        const doc = JSON.parse(res.value);
        if (doc.status === "playing" && doc.players.guest) {
          clearInterval(pollRef.current);
          roomStateRef.current = { code: c, role: myRole, myName: name.trim() };
          onEnterRoom();
        }
      } catch (e) { /* sessizce yut, bir sonraki pollde tekrar dene */ }
    }, 1500);
  }

  useEffect(() => () => clearInterval(pollRef.current), []);

  function copyLink() {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(code).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      });
    }
  }

  return (
    <div className="screen">
      <TopBar onBack={onExit} title="Arkadaşınla Oyna" />

      {mode === "choose" && (
        <div className="lobby-body">
          <input
            className="name-input"
            placeholder="Adını yaz"
            value={name}
            onChange={(e) => setName(e.target.value)}
            maxLength={16}
          />
          {error && <div className="error-text">{error}</div>}
          <button className="menu-card primary" onClick={createRoom}>
            <Users size={20} /><span>Oda Oluştur</span>
          </button>
          <div className="or-divider">veya</div>
          <div className="join-row">
            <input
              className="code-input"
              placeholder="ODA KODU"
              value={joinCode}
              onChange={(e) => setJoinCode(e.target.value.toUpperCase().slice(0, 6))}
              maxLength={6}
            />
            <button className="join-btn" onClick={joinRoom}>Katıl</button>
          </div>
          <p className="lobby-note">
            Not: Bu mod gerçek bir WebSocket sunucusu yerine paylaşımlı depolamayı ~1.5 sn aralıklarla
            kontrol ederek çalışır. Bu dosyayı kendi bilgisayarında çalıştırıyorsan bu paylaşım yalnızca
            aynı tarayıcının farklı sekmeleri arasında geçerlidir — farklı bilgisayarlar arasında oynamak
            için gerçek bir sunucu (Socket.IO vb.) gerekir.
          </p>
        </div>
      )}

      {mode === "waiting" && (
        <div className="lobby-body waiting">
          <div className="code-display">
            <div className="code-label">Davet kodu</div>
            <div className="code-big">{code}</div>
            <button className="copy-btn" onClick={copyLink}>
              {copied ? <Check size={16} /> : <Copy size={16} />} {copied ? "Kopyalandı" : "Kopyala"}
            </button>
          </div>
          <div className="waiting-pulse">
            <Users size={20} />
            <span>Rakip bekleniyor…</span>
          </div>
          <p className="lobby-note">Bu kodu arkadaşına gönder, katıldığında oyun otomatik başlar.</p>
        </div>
      )}
    </div>
  );
}

/* ---------- Çok kişilik: Oyun ekranı ---------- */

function MultiPlay({ onExit, roomStateRef }) {
  const info = roomStateRef.current;
  const role = info?.role;
  const otherRole = role === "host" ? "guest" : "host";
  const code = info?.code;

  const [doc, setDoc] = useState(null);
  const [connError, setConnError] = useState(false);
  const [localAnswered, setLocalAnswered] = useState(false);
  const [secondsLeft, setSecondsLeft] = useState(30);
  const [feedback, setFeedback] = useState(null);
  const [confirmExit, setConfirmExit] = useState(false);
  const pollRef = useRef(null);
  const lastRoundRef = useRef(0);
  const submittingRef = useRef(false);
  const advanceScheduledRef = useRef(0);

  const fetchDoc = useCallback(async () => {
    if (!code) return;
    try {
      const res = await storage.get(`ff-room:${code}`, true);
      if (!res) { setConnError(true); return; }
      const parsed = JSON.parse(res.value);
      setDoc(parsed);
      setConnError(false);
      if (parsed.round !== lastRoundRef.current) {
        lastRoundRef.current = parsed.round;
        setLocalAnswered(false);
        setFeedback(null);
      }
    } catch (e) {
      setConnError(true);
    }
  }, [code]);

  useEffect(() => {
    fetchDoc();
    pollRef.current = setInterval(fetchDoc, 1200);
    return () => clearInterval(pollRef.current);
  }, [fetchDoc]);

  useEffect(() => {
    if (!doc?.roundStartedAt) return;
    const roundSeconds = doc.roundSeconds || 30;
    const tick = () => {
      const elapsed = (Date.now() - doc.roundStartedAt) / 1000;
      const left = Math.max(0, Math.ceil(roundSeconds - elapsed));
      setSecondsLeft(left);
    };
    tick();
    const iv = setInterval(tick, 300);
    return () => clearInterval(iv);
  }, [doc?.roundStartedAt, doc?.round, doc?.roundSeconds]);

  const currentQuestion = doc?.questions?.[doc.round - 1];

  async function submitAnswer(player) {
    if (!doc || localAnswered || submittingRef.current || !currentQuestion) return;
    submittingRef.current = true;
    setLocalAnswered(true);
    const isCorrect = currentQuestion.answers.includes(player.id);
    setFeedback(isCorrect ? "correct" : "wrong");
    try {
      const res = await storage.get(`ff-room:${code}`, true);
      const fresh = JSON.parse(res.value);
      if (fresh.round !== doc.round) { submittingRef.current = false; return; }
      const roundAnswers = fresh.answers[fresh.round] || {};
      if (roundAnswers[role]) { submittingRef.current = false; return; }

      let scoreDelta = 0;
      if (isCorrect) {
        const otherAnsweredCorrectly = roundAnswers[otherRole]?.correct;
        scoreDelta = otherAnsweredCorrectly ? 1 : 3;
      }
      roundAnswers[role] = { correct: isCorrect, playerName: player.name };
      fresh.answers[fresh.round] = roundAnswers;
      fresh.scores[role] = (fresh.scores[role] || 0) + scoreDelta;

      await storage.set(`ff-room:${code}`, JSON.stringify(fresh), true);
    } catch (e) { /* sessiz — bir sonraki poll durumu düzeltecek */ }
    submittingRef.current = false;
  }

  function advanceRound(atRound) {
    setTimeout(async () => {
      try {
        const res = await storage.get(`ff-room:${code}`, true);
        const latest = JSON.parse(res.value);
        if (latest.round !== atRound) return;
        if (latest.round >= TOTAL_ROUNDS) {
          latest.status = "finished";
        } else {
          latest.round += 1;
          latest.roundStartedAt = Date.now();
        }
        await storage.set(`ff-room:${code}`, JSON.stringify(latest), true);
      } catch (e) { /* yut */ }
    }, 2200);
  }

  // host: her iki oyuncu da cevapladıysa turu ilerlet
  useEffect(() => {
    if (!doc || role !== "host" || doc.status !== "playing") return;
    const roundAnswers = doc.answers?.[doc.round] || {};
    if (roundAnswers.host && roundAnswers.guest && advanceScheduledRef.current !== doc.round) {
      advanceScheduledRef.current = doc.round;
      advanceRound(doc.round);
    }
  }, [doc, role]);

  // süre dolduğunda host turu ilerletsin
  useEffect(() => {
    if (secondsLeft > 0 || !doc || doc.status !== "playing" || role !== "host") return;
    const roundAnswers = doc.answers[doc.round] || {};
    if (roundAnswers.host && roundAnswers.guest) return;
    if (advanceScheduledRef.current === doc.round) return;
    advanceScheduledRef.current = doc.round;
    const timeout = setTimeout(async () => {
      try {
        const res = await storage.get(`ff-room:${code}`, true);
        const latest = JSON.parse(res.value);
        if (latest.round !== doc.round) return;
        if (latest.round >= TOTAL_ROUNDS) latest.status = "finished";
        else { latest.round += 1; latest.roundStartedAt = Date.now(); }
        await storage.set(`ff-room:${code}`, JSON.stringify(latest), true);
      } catch (e) { /* yut */ }
    }, 600);
    return () => clearTimeout(timeout);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [secondsLeft, doc?.round]);

  if (!info) {
    return (
      <div className="screen">
        <TopBar onBack={onExit} title="Oda" />
        <p className="lobby-note">Oda bilgisi bulunamadı, lütfen ana menüden tekrar dene.</p>
      </div>
    );
  }

  if (!doc) {
    return (
      <div className="screen">
        <TopBar onBack={onExit} title={`Oda ${code}`} />
        <div className="waiting-pulse"><Wifi size={20} /><span>Bağlanıyor…</span></div>
      </div>
    );
  }

  if (doc.status === "finished") {
    const myScore = doc.scores[role] || 0;
    const otherScore = doc.scores[otherRole] || 0;
    const won = myScore > otherScore;
    const tie = myScore === otherScore;
    return (
      <div className="screen">
        <TopBar onBack={onExit} title="Sonuç" />
        <div className="result-panel">
          <Trophy size={40} />
          <div className="result-title">{tie ? "Berabere!" : won ? "Kazandın!" : "Kaybettin"}</div>
          <div className="result-scores">
            <div><div className="rs-name">{doc.players[role]?.name}</div><ScoreDigits value={myScore} /></div>
            <div className="rs-vs">–</div>
            <div><div className="rs-name">{doc.players[otherRole]?.name}</div><ScoreDigits value={otherScore} /></div>
          </div>
          <button className="menu-card primary" onClick={onExit}><RotateCcw size={18} /><span>Ana Menüye Dön</span></button>
        </div>
      </div>
    );
  }

  const myScore = doc.scores?.[role] || 0;
  const otherScore = doc.scores?.[otherRole] || 0;
  const roundAnswers = doc.answers?.[doc.round] || {};
  const answerNames = currentQuestion ? currentQuestion.answers.map((id) => PLAYERS.find((p) => p.id === id)?.name).filter(Boolean) : [];
  const showReveal = secondsLeft <= 0 || (roundAnswers.host && roundAnswers.guest);
  const multiGameMode = doc.gameMode === "mc" ? "mc" : "type";
  const mcOptions = currentQuestion ? mcOptionsFromQuestion(currentQuestion) : [];

  return (
    <div className="screen">
      <TopBar
        onBack={() => setConfirmExit(true)}
        title={`Oda ${code}`}
        right={connError ? <WifiOff size={16} color="#e4483c" /> : <Wifi size={16} color="#5fd68a" />}
      />

      <div className="hud-row">
        <div className="hud-chip">
          <div className="hud-label">Tur</div>
          <div className="hud-value">{doc.round}/{TOTAL_ROUNDS}</div>
        </div>
        <div className={"hud-chip timer" + (secondsLeft <= 10 ? " urgent" : "")}>
          <div className="hud-label">Süre</div>
          <ScoreDigits value={secondsLeft} />
        </div>
        <div className="hud-chip">
          <div className="hud-label">Skor</div>
          <div className="hud-value">{myScore} - {otherScore}</div>
        </div>
      </div>

      <div className="timer-track">
        <div
          className={"timer-fill" + (secondsLeft <= 10 ? " urgent" : "")}
          style={{ width: `${Math.max(0, (secondsLeft / (doc.roundSeconds || 30)) * 100)}%` }}
        />
      </div>

      <div className="vs-names">
        <span className={roundAnswers[role] ? "answered" : ""}>{doc.players[role]?.name} (sen)</span>
        <span className={roundAnswers[otherRole] ? "answered" : ""}>{doc.players[otherRole]?.name}</span>
      </div>

      {currentQuestion && (
        <div className={"matchup " + (feedback === "correct" ? "flash-green" : feedback === "wrong" ? "flash-red" : "")}>
          <ClubCrest clubId={currentQuestion.clubA} />
          <div className="vs">
            VS
            <span className={"diff-badge " + difficultyInfo(currentQuestion.answers.length).cls}>
              {difficultyInfo(currentQuestion.answers.length).label}
            </span>
          </div>
          <ClubCrest clubId={currentQuestion.clubB} />
        </div>
      )}

      {showReveal && currentQuestion && (
        <div className="reveal-banner reveal-ok">
          Doğru cevap: <strong>{answerNames.join(" / ")}</strong>
        </div>
      )}

      {multiGameMode === "mc" ? (
        <MultipleChoiceAnswer
          options={mcOptions}
          correctIds={currentQuestion?.answers}
          disabled={localAnswered || showReveal}
          onSubmit={submitAnswer}
          revealCorrectId={doc.round}
        />
      ) : (
        <AnswerInput
          disabled={localAnswered || showReveal}
          onSubmit={submitAnswer}
          revealCorrectId={doc.round}
        />
      )}

      {confirmExit && (
        <ConfirmExitModal onConfirm={onExit} onCancel={() => setConfirmExit(false)} />
      )}
    </div>
  );
}

